SELECT m.outTradeId, m.totalFee, m.payment, m.nasOuid, m.created, m.num, d.outOrderId, d.title, d.outItemId, d.outerSkuId, d.orderNum, d.orderTotalFee, d.orderPayment, d.orderPrice FROM ( SELECT outTradeId, totalFee, payment, nasOuid, created, num FROM nanXOrderMaster
outTradeId > #{after}
ORDER BY outTradeId OFFSET 0 ROWS FETCH FIRST #{limit} ROWS ONLY ) m LEFT JOIN nanXOrderDetail d ON m.outTradeId = d.outTradeId
